use super::*;
const A:&str="10000000-0000-4000-8000-000000000001";
const I:&str="20000000-0000-4000-8000-000000000001";
fn fixture()->Connection{let c=Connection::open_in_memory().unwrap();local_db::ensure_schema(&c).unwrap();c.execute_batch("CREATE TABLE local_users(id TEXT PRIMARY KEY,central_user_id TEXT,role TEXT,is_active INTEGER,offline_expires_at TEXT,permissions_json TEXT);CREATE TABLE local_session(id INTEGER PRIMARY KEY,user_id TEXT);CREATE TABLE local_inventory_movement_records(movement_id TEXT PRIMARY KEY,item_id TEXT,movement_json TEXT,account_id TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);INSERT INTO local_users VALUES('a','10000000-0000-4000-8000-000000000001','admin',1,datetime('now','+1 hour'),'[\"inventory.view\",\"inventory.import\",\"inventory.create\",\"inventory.edit\",\"inventory.adjust_stock\",\"finance.view\",\"finance.create_expense\"]');INSERT INTO local_session VALUES(1,'a');").unwrap();inventory::write(&c,&[json!({"id":I,"name":"old","type":"tool","sku":null,"category":null,"unit":null,"status":"available","initial_quantity":10,"current_quantity":10,"sync_version":4})]).unwrap();c.execute("INSERT INTO sync_state(key,value) VALUES(?1,'[]')",[local_db::scoped_state_key(&c,"finance_transactions_state").unwrap()]).unwrap();c}
fn payload()->Value{let batch=local_db::new_uuid();let new=local_db::new_uuid();json!({"rows":[{"operation":"update","record":{"id":I,"name":"old","type":"tool","sku":null,"category":null,"unit":null,"status":"available","initial_quantity":10,"current_quantity":12,"unit_cost":5,"supplier":null,"storage_location":null}},{"operation":"create","record":{"id":new,"name":"new","type":"tool","sku":null,"category":null,"unit":null,"status":"available","initial_quantity":3,"current_quantity":3,"unit_cost":2,"supplier":null,"storage_location":null}}],"batches":[{"id":batch,"transaction_id":local_db::new_uuid(),"reference":"purchase","purchase_date":"2026-11-06","currency":"USD","project_id":null,"supplier":null,"invoice_number":null,"notes":null}],"lines":[{"id":local_db::new_uuid(),"movement_id":local_db::new_uuid(),"item_id":I,"purchase_batch_id":batch,"quantity":2,"unit_cost":5,"tax":1,"line_total":11,"notes":null,"storage_location":null},{"id":local_db::new_uuid(),"movement_id":local_db::new_uuid(),"item_id":new,"purchase_batch_id":batch,"quantity":3,"unit_cost":2,"tax":0,"line_total":6,"notes":null,"storage_location":null}],"inventory_protocol":2,"item_bases":[]})}
fn base(c:&Connection)->String{json!(inventory::read(c).unwrap().unwrap()).to_string()}
#[test]fn purchase_commits_one_intent_stock_history_expense_and_dependency_chain(){let mut c=fixture();let base=base(&c);let payload=payload();let change=local_db::new_uuid();let result=import(&mut c,&payload.to_string(),&base,A,&change).unwrap();assert_eq!(result["imported"],2);assert_eq!(result["expense_total"],17.0);assert_eq!(result["created_items"],1);assert_eq!(inventory::read(&c).unwrap().unwrap()[0]["current_quantity"],12);assert_eq!(local_excel::cached_rows(&c,"finance_transactions_state").unwrap()[0]["amount"],17.0);assert_eq!(c.query_row("SELECT COUNT(*) FROM local_inventory_movement_records",[],|r|r.get::<_,i64>(0)).unwrap(),2);assert!(inventory::pending_items(&c).unwrap().contains(I));crate::local_inventory::cache_movements(&mut c,I,"[]",A).unwrap();assert_eq!(c.query_row("SELECT COUNT(*) FROM local_inventory_movement_records",[],|r|r.get::<_,i64>(0)).unwrap(),2);assert!(crate::local_finance::pending_ids(&c,"transaction").unwrap().contains(payload["batches"][0]["transaction_id"].as_str().unwrap()));assert_eq!(import(&mut c,&payload.to_string(),&base,A,&change).unwrap(),result);assert_eq!(c.query_row("SELECT COUNT(*) FROM sync_outbox",[],|r|r.get::<_,i64>(0)).unwrap(),1);let mut next=inventory::read(&c).unwrap().unwrap();let mut edit=json!({"id":I,"patch":{"name":"later"}});inventory::stamp_versions(&c,"item",Some(I),"update",&mut edit,&mut next).unwrap();assert_eq!(edit["item_bases"][0]["depends_on"],change);}
#[test]fn purchase_rejects_stale_scope_tampering_and_queue_failure_atomically(){for fault in ["stale","account","quantity","identity","permission","queue"]{let mut c=fixture();let before=base(&c);let mut input=payload();if fault=="quantity"{input["rows"][0]["record"]["current_quantity"]=json!(99);}if fault=="identity"{input["lines"][1]["id"]=input["lines"][0]["id"].clone();}if fault=="permission"{c.execute("UPDATE local_users SET permissions_json='[\"inventory.view\",\"inventory.import\",\"inventory.create\",\"inventory.edit\",\"finance.view\",\"finance.create_expense\"]'",[]).unwrap();}if fault=="queue"{c.execute_batch("CREATE TRIGGER reject_purchase BEFORE INSERT ON sync_outbox BEGIN SELECT RAISE(ABORT,'injected'); END;").unwrap();}assert!(import(&mut c,&input.to_string(),if fault=="stale"{"[]"}else{&before},if fault=="account"{"other"}else{A},&local_db::new_uuid()).is_err(),"{fault}");assert_eq!(base(&c),before,"{fault}");assert!(local_excel::cached_rows(&c,"finance_transactions_state").unwrap().is_empty());assert_eq!(c.query_row("SELECT COUNT(*) FROM local_inventory_movement_records",[],|r|r.get::<_,i64>(0)).unwrap(),0);assert_eq!(c.query_row("SELECT COUNT(*) FROM sync_outbox",[],|r|r.get::<_,i64>(0)).unwrap(),0);}}
